class BankAccount:
    def __init__(self, initial_balance=0):
        self.balance = initial_balance

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            print(f"Balance: ${self.balance}")
        else:
            print("Deposit amount must be positive.")

    def withdraw(self, amount):
        if amount > 0 and self.balance >= amount:
            self.balance -= amount
            print(f"Balance: ${self.balance}")
        else:
            print("Insufficient funds or withdrawal amount must be positive.")


# Example usage:
account = BankAccount()

while True:
    command = input("Enter a command (deposit, withdraw, or exit): ").lower()

    if command == "deposit":
        deposit_amount = float(input("Enter the amount to deposit: "))
        account.deposit(deposit_amount)

    elif command == "withdraw":
        withdraw_amount = float(input("Enter the amount to withdraw: "))
        account.withdraw(withdraw_amount)

    elif command == "exit":
        print("Exiting the bank account simulator...")
        break

    else:
        print("Invalid command. Please try again.")
```

This function allows the user to interact with the bank account by entering commands like `deposit 100` or `withdraw 50`. The function validates the input and updates the balance accordingly. The user can continue interacting with the account until they enter the `exit` command.
